import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    M = data[1]
    T = data[2:2 + M]

    length = N
    for t in T:
        length -= length // t

    K = min(length, 10000)
    pos = list(range(1, K + 1))

    for t in reversed(T):
        d = t - 1
        if d >= pos[-1]:
            continue
        if d == 1:
            pos = [(x << 1) - 1 for x in pos]
        else:
            pos = [x + (x - 1) // d for x in pos]

    sys.stdout.write('\n'.join(map(str, pos)))
    sys.stdout.write('\n')

if __name__ == "__main__":
    main()
